SM.CMD_FRAME=L('{h}は低い声で「{c}」と囁いた。|{h}は耳元で「{c}」と囁いた。|{h}は{a}の目を覗き込み、ゆっくりと「{c}」と告げた。|{h}は{a}の額に指先を当てて、「{c}」と言い聞かせた。|{h}の静かな声が、「{c}」と染み込んでいった。|{h}は指を一度鳴らしてから、「{c}」と囁いた。|{h}は{a}の名前を呼び、続けて「{c}」と命じた。|{h}は息がかかるほど顔を寄せて、「{c}」と囁いた。');
SM.EVENTS=[
{id:'phone',t:L('{a}のスマホが鳴った。着信音が、静かな部屋に響き渡った。|玄関のチャイムが鳴った。宅配便だった。'),fx:{depth: -18}},
{id:'deepen',t:L('{h}は「もっと深く。もっと深く」と繰り返した。{a}の頭が、さらに深い場所へ沈んでいった。|窓の外で雨が降り出した。雨音に包まれて、{a}はさらに深く落ちていった。'),fx:{depth:15}},
{id:'backfire',t:L('{h}は振り子を見つめすぎて、自分まで瞼が重くなってきた。慌てて頬を叩いた。|{h}は興奮のあまり、暗示の言葉を言い間違えた。{a}が「……ん？」と首を傾げた。'),fx:{depth: -10,hypno:1}},
{id:'sleeptalk',t:L('{a}が寝言のように誰かの名前を呟いた。{h}ではない名前だった。{h}の顔が引きつった。|{a}は深い催眠の中で、昔の恋人の名前を呼んだ。'),fx:{jealous:1}},
{id:'battery',t:L('催眠アプリの画面が、充電切れで真っ暗になった。|お香の火が消えた。部屋の甘い香りが、少しずつ薄れていった。'),fx:{depth: -12}},
{id:'cat',t:L('どこからか猫が入ってきて、{a}の膝に飛び乗った。{a}はぼんやりしたまま、猫を撫で始めた。|隣の部屋から、テレビの笑い声が聞こえた。'),fx:{depth: -6}},
{id:'record',t:L('{h}は三脚にスマホを立て、録画を始めた。「後で見返すために」|{h}は{a}の蕩けた顔を、何枚も写真に収めた。'),fx:{record:1}},
{id:'tears',t:L('{a}の目から、すっと涙が一筋流れた。催眠の奥で、{a}の何かが泣いていた。{h}の手が止まった。|{a}は「……たすけて｜……助けてくれ｜……助けてください」と小さく呟いた。{h}は聞こえなかったふりをした。'),fx:{guilt:1,depth: -5}},
{id:'body',t:L('{a}の下腹に、うっすらと紋様のような赤みが浮かんでいた。暗示が、体に染み込んでいるようだった。|{a}は暗示がなくても、{h}の声を聞くだけで体が反応するようになっていた。'),fx:{fall:8,depth:6}},
{id:'half',t:L('{a}が半分だけ目を開けた。「……{you}……？」――{h}は慌てて指を鳴らし、{a}をまた眠りに戻した。|{a}は一瞬、今の状況を理解しかけた。その目に、恐怖と、それ以外の何かが浮かんだ。'),fx:{depth: -14,aware:1}},
{id:'clock',t:L('壁の時計が、ちょうど零時を打った。その音で、{a}は深い眠りの底へ沈んだ。'),fx:{depth:10}},
{id:'knock',t:L('誰かがドアをノックした。「{a}？　いるの？」――友人の声だった。{h}は息を潜めた。'),fx:{depth: -15,risk:1}}
];
SM.AFTER={
peace:L('翌日、{a}はテストで満点を取った。「{you}のおかげだよ！｜{you}のおかげだ！｜{you}のおかげです！」――{a}は満面の笑みでお礼を言った。|{a}は仕事の資料を半日で仕上げ、上司に褒められた。「また、あの催眠お願いしてもいい？｜また、あの催眠を頼んでもいいか？｜また、あの催眠をお願いしてもいいですか？」'),
forget:L('目を覚ました{a}は、何も覚えていなかった。「あれ、寝ちゃってた？　ごめん｜あれ、寝ていたか？　すまない｜あれ、寝ていましたか？　すみません」――{h}は「疲れてたんだよ」と笑った。|{a}は「なんか、いい夢見た気がする｜何だか、いい夢を見た気がする｜何だか、いい夢を見た気がします」と伸びをした。{h}は何も言わなかった。'),
body:L('{a}は何も覚えていなかった。ただ、{h}の声を聞くたびに、なぜか体の奥が疼いた。|{a}は数日後、気づけば{h}の家の前に立っていた。なぜ来たのか、自分でも分からなかった。'),
angry:L('{a}は全部覚えていた。目を覚ました瞬間、{h}の頬を思い切り張り飛ばした。「二度と近寄るな｜＝｜二度と近寄らないでください」|{a}は震える声で言った。「……最低。本当に、最低｜……最低だ。本当に、最低だ｜……最低です。本当に、最低です」――ドアが乱暴に閉まった。'),
report:L('{a}は翌朝、警察に相談した。{h}のスマホからは、{a}の映像が見つかった。|{a}は会社の相談窓口にすべてを話した。一週間後、{h}の机は空になっていた。'),
revenge:L('一週間後、{a}は同じ振り子を手に、{h}の前に現れた。「今度は、あなたの番｜今度は、あなたの番だ｜今度は、あなたの番です」|{a}は{h}の弱みを調べ上げ、すべてを{h}の周囲にばらまいた。'),
counter:L('{a}は{h}の目をまっすぐ見つめ返した。「……三つ数えたら、あなたは眠る｜＝｜……三つ数えたら、あなたは眠ります」――逆催眠だった。崩れ落ちた{h}を、{a}は冷たく見下ろした。|{a}は{h}の振り子を奪い、{h}の目の前で揺らした。今度は{h}の瞳が、焦点を失っていった。'),
sweet:L('{a}は顔を真っ赤にして、{h}の胸を叩いた。「ばか。……でも、またしてもいいよ｜ばか。……だが、またしてもいい｜ばか。……でも、またしてもいいですよ」|{a}は{h}に背を向けたまま、「次は、もっと優しくして｜次は、もっと優しくしろ｜次は、もっと優しくしてください」と小さな声で言った。'),
shy:L('{a}は覚えていた。顔から火が出そうで、{h}の顔をまともに見られなかった。それから一週間、{a}は{h}を避け続けた。|{a}は布団にくるまって、一日中出てこなかった。'),
fall:L('三日後、{a}は自分から{h}の部屋を訪ねた。「……あの、また、かけてくれない？｜……その、また、かけてくれないか？｜……あの、また、かけてくれませんか？」|{a}は{h}の前に跪いて、自分から振り子を差し出した。「お願い。もう一回、私を壊して｜頼む。もう一度、私を壊してくれ｜お願いです。もう一度、私を壊してください」'),
couple:L('{a}は覚えていた。けれど、怒る代わりに{h}の手を握った。「……順番が逆だよ。ちゃんと、告白からやり直して｜……順番が逆だ。ちゃんと、告白からやり直せ｜……順番が逆です。ちゃんと、告白からやり直してください」|それから二人は、付き合うことになった。始まり方は、誰にも言えなかった。'),
depend:L('{a}は{h}を憎んでいた。それなのに、{h}の声を聞かないと眠れなくなっていた。|{a}は{h}を突き放せなかった。憎しみと快楽が、もう区別できなかった。'),
laugh:L('{a}は腹を抱えて笑った。「催眠とか、本気で信じてたの？　かわいいとこあるじゃん｜催眠など、本気で信じていたのか？　かわいいところもあるものだ｜催眠なんて、本気で信じていたんですか？　かわいいところがありますね」|{a}は「次はもっと練習してきなよ｜次はもっと練習してこい｜次はもっと練習してきてください」と、{h}の肩を叩いた。'),
noticed:L('{a}は途中で、すべてに気づいた。「……何をしようとしてたの？｜……何をしようとしていた？｜……何をしようとしていたんですか？」――{h}は答えられなかった。|{a}はかからなかった。かかったふりをして、{h}が何をするのか、最後まで見届けた。')
};
SM.AFTER.confused=L('{a}は全部覚えていた。けれど、怒ればいいのか、泣けばいいのか、自分でも分からなかった。{h}の顔を見るたびに言葉を探して、結局何も言えないまま目を逸らした。|{a}は自分の手のひらを、しばらくじっと見つめていた。「……あれ、本当に私だったの？｜……あれは、本当に私だったのか？｜……あれ、本当に私だったんですか？」――{h}は答えなかった。{a}も、答えが欲しいのかどうか分からなかった。|{a}は家に帰ってから、ベッドの端に座ったまま朝を迎えた。嫌だったのか、嫌じゃなかったのか。どちらと言い切っても、嘘になる気がした。');
SM.AFTER.dazed=L('{a}は目を覚ましてからも、しばらく天井を見つめたまま動かなかった。{h}が名前を呼んでも、返事は一拍遅れて返ってきた。心だけが、まだあの場所に置き去りになっていた。|翌日、{a}は一日じゅう上の空だった。お茶を淹れたまま飲み忘れ、話しかけられても「……え？」と聞き返してばかりいた。耳の奥に、まだ{h}の声が残っていた。|{a}はぼんやりしたまま服を着て、ぼんやりしたまま家に帰った。玄関で靴を脱いだところで、急に膝の力が抜けて、そのまま座り込んだ。何を考えればいいのかも、分からなかった。');
SM.AFTER.accept=L('{a}は全部覚えていた。長い沈黙のあとで、{a}は小さく息を吐いた。「……びっくりした。でも、{you}だったから、いい｜……驚いた。だが、{you}だったから、いい｜……びっくりしました。でも、{you}だったから、いいです」――{h}は、ほっとしたように肩を落とした。|{a}は戸惑った顔のまま、{h}の袖をそっと掴んだ。「次は、ちゃんと最初から言って。……そしたら、たぶん、断らないから｜次は、ちゃんと最初から言え。……そうすれば、たぶん、断らない｜次は、ちゃんと最初から言ってください。……そうしたら、たぶん、断りません」――{h}は何度も頷いた。{a}は赤い顔のまま、掴んだ袖を離さなかった。|{a}はしばらく黙って{h}を見ていた。それから、困ったように笑った。「怒るタイミング、逃しちゃった。……もういいよ。そのかわり、ちゃんと責任とってね｜怒るタイミングを、逃してしまった。……もういい。その代わり、ちゃんと責任を取れ｜怒るタイミングを、逃してしまいました。……もういいです。その代わり、ちゃんと責任を取ってくださいね」――{h}は、神妙な顔で頷いた。');
